1	/* environment.c — the environment block a process sees (Sprint 044, family "environment").
2	 *
3	 * No C runtime; built as a GUI program, as the launcher is. The launcher's C runtime asks for its
4	 * environment after its code pages (frontier 2026-10-10, 18,036 instructions): GetEnvironmentStringsW,
5	 * then FreeEnvironmentStringsW, its only environment imports. Started by cmd (the parent), the binary
6	 * starts itself twice with no inherited handles and CREATE_UNICODE_ENVIRONMENT: once with a block of
7	 * five entries in no sorted order, one of them a drive variable ("=C:=..."), and once with an empty
8	 * block. Each child prints what it sees to a file the parent copies to its standard output:
9	 *   - the block's entries in order and its length in UTF-16 units, the final NUL included
10	 *   - a second call: a different pointer or the same, the same content, and whether a write into the
11	 *     first copy shows in the second
12	 *   - HeapSize(GetProcessHeap()) of the block, beside its length in bytes
13	 *   - FreeEnvironmentStringsW's return and last error (after SetLastError(0xDEAD))
14	 */
15	#include <windows.h>
16	
17	#define SENTINEL 0xDEADu
18	
19	static char out[16384];
20	static unsigned n;
21	
22	static void put(const char *s) { while (*s) out[n++] = *s++; }
23	static void putu(unsigned long long v) {
24	    char t[24];
25	    int k = 0;
26	    do { t[k++] = (char)('0' + v % 10); v /= 10; } while (v);
27	    while (k) out[n++] = t[--k];
28	}
29	static void row(const char *s) { put("{\"s\":\""); put(s); put("\""); }
30	static void field(const char *k, unsigned long long v) { put(",\""); put(k); put("\":"); putu(v); }
31	static void flag(const char *k, int v) { put(",\""); put(k); put(v ? "\":true" : "\":false"); }
32	static void end(void) { put("}\n"); }
33	
34	static void wide_item(const WCHAR *w) {                   /* a JSON string: ASCII, '?' elsewhere */
35	    out[n++] = '"';
36	    for (; *w; w++) {
37	        WCHAR c = *w;
38	        if (c == '\\' || c == '"') out[n++] = '\\';
39	        out[n++] = (c >= 32 && c < 127) ? (char)c : '?';
40	    }
41	    out[n++] = '"';
42	}
43	
44	static DWORD block_length(const WCHAR *b) {              /* units through the final NUL; 1 for an empty block */
45	    if (!b[0]) return 1;
46	    DWORD i = 0;
47	    while (b[i] || b[i + 1]) i++;
48	    return i + 2;
49	}
50	
51	static const WCHAR SET_BLOCK[] = L"ZED=last\0alpha=1\0=C:=C:\\w2m\0SteamAppId=480\0Path=C:\\Windows\\system32\0";
52	static const WCHAR EMPTY_BLOCK[] = L"\0";
53	
54	static int arg_is(const WCHAR *word) {
55	    const WCHAR *c = GetCommandLineW();
56	    DWORD len = 0, w = 0;
57	    while (c[len]) len++;
58	    while (word[w]) w++;
59	    if (len < w + 1 || c[len - w - 1] != ' ') return 0;
60	    for (DWORD i = 0; i < w; i++) if (c[len - w + i] != word[i]) return 0;
61	    return 1;
62	}
63	
64	static void child(const WCHAR *rows_file) {
65	    SetLastError(SENTINEL);
66	    WCHAR *b = GetEnvironmentStringsW();
67	    DWORD err = GetLastError();
68	    DWORD len = b ? block_length(b) : 0;
69	    row("block"); flag("null", b == 0); field("err", err); field("length", len);
70	    put(",\"entries\":[");
71	    int first = 1;
72	    for (const WCHAR *p = b; p && *p; p += lstrlenW(p) + 1) {
73	        if (!first) put(",");
74	        wide_item(p);
75	        first = 0;
76	    }
77	    put("]"); end();
78	
79	    WCHAR *b2 = GetEnvironmentStringsW();
80	    int same = b2 && block_length(b2) == len;
81	    for (DWORD i = 0; same && i < len; i++) same = b[i] == b2[i];
82	    row("second_call"); flag("same_pointer", b2 == b); flag("same_content", same); end();
83	
84	    int shows = 0;
85	    if (b && b2 && b2 != b && b[0]) {
86	        WCHAR saved = b[0];
87	        b[0] = 'Q';
88	        WCHAR *b3 = GetEnvironmentStringsW();
89	        shows = b3 && b3[0] == 'Q';
90	        b[0] = saved;
91	        if (b3) FreeEnvironmentStringsW(b3);
92	    }
93	    row("copy"); flag("write_shows_in_next_call", shows); end();
94	
95	    SIZE_T size = b ? HeapSize(GetProcessHeap(), 0, b) : 0;
96	    row("heap"); field("heap_size", size == (SIZE_T)-1 ? 0 : size); field("length_bytes", (unsigned long long)len * sizeof(WCHAR));
97	    end();
98	
99	    SetLastError(SENTINEL);
100	    BOOL ok = FreeEnvironmentStringsW(b2);
101	    err = GetLastError();
102	    row("free"); field("ret", ok != 0); field("err", err); end();
103	    FreeEnvironmentStringsW(b);
104	
105	    HANDLE f = CreateFileW(rows_file, GENERIC_WRITE, 0, NULL, CREATE_ALWAYS, FILE_ATTRIBUTE_NORMAL, NULL);
106	    DWORD w;
107	    WriteFile(f, out, n, &w, NULL);
108	    CloseHandle(f);
109	}
