111	static DWORD run_child(const WCHAR *word, const WCHAR *block, const WCHAR *rows_file, char *dst, DWORD cap) {
112	    static WCHAR self[600], cmd[700];
113	    DWORD len = GetModuleFileNameW(NULL, self, 300), k = 0;
114	    cmd[k++] = '"';
115	    for (DWORD i = 0; i < len; i++) cmd[k++] = self[i];
116	    cmd[k++] = '"';
117	    cmd[k++] = ' ';
118	    for (DWORD i = 0; word[i]; i++) cmd[k++] = word[i];
119	    cmd[k] = 0;
120	    STARTUPINFOW si;
121	    unsigned char *b = (unsigned char *)&si;
122	    for (unsigned i = 0; i < sizeof si; i++) b[i] = 0;
123	    si.cb = sizeof si;
124	    PROCESS_INFORMATION pi;
125	    DeleteFileW(rows_file);
126	    if (!CreateProcessW(self, cmd, NULL, NULL, FALSE, CREATE_UNICODE_ENVIRONMENT, (LPVOID)block, NULL, &si, &pi))
127	        ExitProcess(2);
128	    WaitForSingleObject(pi.hProcess, 60000);
129	    CloseHandle(pi.hThread);
130	    CloseHandle(pi.hProcess);
131	    HANDLE f = CreateFileW(rows_file, GENERIC_READ, 0, NULL, OPEN_EXISTING, FILE_ATTRIBUTE_NORMAL, NULL);
132	    if (f == INVALID_HANDLE_VALUE) ExitProcess(3);
133	    DWORD got = 0;
134	    ReadFile(f, dst, cap, &got, NULL);
135	    CloseHandle(f);
136	    DeleteFileW(rows_file);
137	    return got;
138	}
