140	/* The child's rows, each name prefixed with its start ("set." or "empty."). */
141	static DWORD prefixed(const char *prefix, const char *rows, DWORD count, char *dst) {
142	    DWORD k = 0;
143	    for (DWORD i = 0; i < count; i++) {
144	        dst[k++] = rows[i];
145	        if (i >= 5 && rows[i - 5] == '{' && rows[i - 3] == 's' && rows[i - 1] == ':' && rows[i] == '"')
146	            for (const char *p = prefix; *p; p++) dst[k++] = *p;
147	    }
148	    return k;
149	}
150	
151	void start(void) {
152	    if (arg_is(L"child-set")) { child(L"w2m-environment-set.jsonl"); ExitProcess(0); }
153	    if (arg_is(L"child-empty")) { child(L"w2m-environment-empty.jsonl"); ExitProcess(0); }
154	    static char rows[16384], all[40000];
155	    DWORD k = 0, got;
156	    got = run_child(L"child-set", SET_BLOCK, L"w2m-environment-set.jsonl", rows, sizeof rows);
157	    k += prefixed("set.", rows, got, all + k);
158	    got = run_child(L"child-empty", EMPTY_BLOCK, L"w2m-environment-empty.jsonl", rows, sizeof rows);
159	    k += prefixed("empty.", rows, got, all + k);
160	    DWORD w;
161	    WriteFile(GetStdHandle(STD_OUTPUT_HANDLE), all, k, &w, NULL);
162	    ExitProcess(0);
163	}

